void Reset_Handler(void) {
    uint32_t *src = &_sidata;
    uint32_t *dst = &_sdata;
    while (dst < &_edata)
        *dst++ = *src++;
    // memset wants bytes, not words
    memset(&_sbss, 0,
           (uint8_t *)&_ebss - (uint8_t *)&_sbss);
    main();
    for (;;) {}
}
